import { Collapsible } from '@absoluteui/components/collapsible';

const host = document.createElement('div');
document.body.append(host);
Collapsible.create(host, {
  label: 'How is the delivery date calculated?',
  content: 'Orders placed before 14:00 on a business day ship the same day. Weekends and public holidays are not counted.',
});

import { Collapsible, type CollapsibleChangeDetail } from '@absoluteui/components/collapsible';
import { Switch } from '@absoluteui/components/switch';

const host = document.createElement('section');
const settings = document.createElement('div');
const cacheHost = document.createElement('div');
settings.append(cacheHost);
document.body.append(host);
Switch.create(cacheHost, { label: 'Cache responses for offline use' });
Collapsible.create(host, { label: 'Advanced settings', content: settings, headingLevel: 3, variant: 'bordered' });
// Remember that the user has seen the advanced settings (aui-change fires only on user toggles).
host.addEventListener('aui-change', (event) => {
  if ((event as CustomEvent<CollapsibleChangeDetail>).detail.open) host.dataset.viewed = 'true';
});
